attributes._cssText:
:root {
  --stone-50: #fafaf9;
  --stone-100: #f5f5f4;
  --stone-200: #f0eeed;
  --stone-300: #d6d3d1;
  --stone-400: #a6a09b;
  --stone-500: #75726f;
  --stone-600: #57534e;   
  --stone-700: #44403b;
  --stone-800: #292524;
  --stone-950: #0c0a09;
  --cream: #f0eee9;
  --cream-lighter: #fafaf9;
  --black: #000;
  --r-card: 1.75rem;                 
  --gutter: 0.75rem;                 
  --container: min(100vw, 94.5rem);
  --col-w: calc((var(--container) - 17 * var(--gutter)) / 16);   
  --pad-x: max(var(--gutter), calc((100vw - var(--container)) / 2));   
  --font-sans: 'Hanken Grotesk', 'Pretendard Variable', Pretendard, sans-serif;
  --font-display: 'Syne', 'Pretendard Variable', sans-serif;   
  --ease-cursor: cubic-bezier(0.38, 0.12, 0.29, 1);
  --spring-soft: cubic-bezier(0.34, 1.3, 0.64, 1);   
  --spring-flat: cubic-bezier(0.22, 1, 0.36, 1);     
  --spring-land: var(--spring-flat);                 
  --green: #16a34a;              
  --dom-a-ink: #1c1917;  --dom-a-bar: #292524;  --dom-a-tint: #e7e5e4;   
  --dom-b-ink: #1e40af;  --dom-b-bar: #1d4ed8;  --dom-b-tint: #e3eaf7;   
  --dom-p-ink: #92400e;  --dom-p-bar: #d97706;  --dom-p-tint: #fbeedc;   
  --shadow-2xl: 0 25px 50px -12px rgba(0, 0, 0, 0.25);
}
@supports (transition-timing-function: linear(0, 1)) {
  :root {
    --spring-land: linear(0, 0.1271 2.87%, 0.2372 5.52%, 0.3339 8.04%, 0.4199 10.49%, 0.4969 12.91%, 0.5663 15.34%,
      0.6291 17.82%, 0.6858 20.38%, 0.7373 23.08%, 0.7838 25.95%, 0.8256 29.04%, 0.8631 32.43%, 0.8962 36.2%,
      0.9252 40.45%, 0.9499 45.35%, 0.9704 51.13%, 0.9864 58.18%, 0.9979 67.22%, 1 70%, 1);
  }
}
* { margin: 0; padding: 0; box-sizing: border-box; }
button, input, select, textarea { font-family: inherit; }
:focus-visible { outline: none !important; }
html { touch-action: pan-x pan-y; background: var(--stone-50); }   
.squircle { corner-shape: superellipse(1.3); }
body { isolation: isolate; }
body {
  background: var(--stone-50);
  color: var(--black);
  font-family: var(--font-sans);
  font-size: 16px;
  line-height: 1.5;
  font-weight: 500;
  -webkit-font-smoothing: antialiased;
  overflow-x: clip;
}
body.locked { overflow: hidden; }
body.modal-locked { overflow: hidden; }   
html:has(body.locked), html:has(body.modal-locked) { overflow: hidden; }
body.locked, html:has(body.locked) { background: #373534; }
body.modal-locked, html:has(body.modal-locked) { background: #4f4d4c; }
html { overflow-y: auto; }
body { overflow-wrap: anywhere; }
* { scrollbar-width: none; }                 
*::-webkit-scrollbar { width: 0 !important; height: 0 !important; display: none; }   
.ov-scrollthumb {                                         
  position: fixed; width: 6px; border-radius: 999px;
  background: rgba(140, 140, 140, 0.5);
  opacity: 1;                 
  z-index: 1500; pointer-events: auto; cursor: default;
  transform-origin: center;
  transition: opacity 0.35s ease, background-color 0.15s, transform 0.12s, visibility 0s;   
}
.ov-scrollthumb.ov-off { opacity: 0 !important; pointer-events: none; visibility: hidden; transition: opacity 0.35s ease, background-color 0.15s, transform 0.12s, visibility 0s linear 0.35s; }   
.ov-scrollthumb.ov-autohide { opacity: 0; pointer-events: none; }
.ov-scrollthumb.ov-autohide.show:not(.ov-off),
.ov-scrollthumb.ov-autohide:hover:not(.ov-off),
.ov-scrollthumb.ov-autohide.dragging { opacity: 1; pointer-events: auto; }
.type-toggle[hidden], .pill-btn[hidden], .field[hidden], .timeline[hidden] { display: none !important; }
body.set-tab-share .ov-scrollthumb.ov-tab,
body.set-tab-anim  .ov-scrollthumb.ov-tab,
body.ac-deep       .ov-scrollthumb.ov-ac-list,
body.ac-deep       .ov-scrollthumb.ov-ac-chart,
body:not(.ac-deep) .ov-scrollthumb.ov-ac-detail,
body:not(.ac-tab1) .ov-scrollthumb.ov-ac-chart,
body.ac-tab1       .ov-scrollthumb.ov-ac-list {
  visibility: hidden !important; opacity: 0 !important;
  pointer-events: none !important; transition: none !important;
}
.ov-scrollthumb:hover, .ov-scrollthumb.dragging { background: rgba(140, 140, 140, 0.82); transform: scaleX(1.34); }   
.scroll-edge {
  position: fixed; right: 26px; bottom: 26px; z-index: 1400;
  width: 48px; height: 48px; border-radius: 50%;
  display: flex; align-items: center; justify-content: center;
  background: rgba(250, 250, 249, 0.55);
  border: 0.5px solid rgba(12, 10, 9, 0.16);
  backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
  color: var(--black);
  cursor: pointer;
  opacity: 0; visibility: hidden; transform: translateY(10px) scale(0.9); pointer-events: none;
  transition: opacity 0.32s ease, transform 0.32s ease, background-color 0.15s, visibility 0.32s;
}
.scroll-edge.show { opacity: 1; visibility: visible; transform: translateY(0) scale(1); pointer-events: auto; }
.scroll-edge:hover { background: rgba(250, 250, 249, 0.8); }
.scroll-edge:active { transform: translateY(0) scale(0.94); }
.scroll-edge svg { transition: transform 0.38s cubic-bezier(0.34, 1.3, 0.5, 1); display: block; }
.scroll-edge.up svg { transform: rotate(180deg); }
body.locked .scroll-edge, body.modal-locked .scroll-edge { opacity: 0 !important; visibility: hidden !important; pointer-events: none !important; }
::selection { background: var(--black); color: var(--cream); }
.serif { font-family: var(--font-sans); font-style: normal; font-weight: 600; }   
.boot {
  position: fixed; inset: 0; z-index: 5000;
  background: var(--stone-50);
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: 1.1rem;
  transition: opacity 0.5s ease, visibility 0.5s;
}
.boot.done { opacity: 0; visibility: hidden; pointer-events: none; }
.boot-mark { width: 5.5rem; height: 5.5rem; }
.boot-word {
  font-family: var(--font-display); font-weight: 600;   
  font-size: 1.4rem;
  color: var(--black);
  opacity: 0;
  transform: translateY(10px);
  animation: bootWord 0.6s var(--spring-flat) 0.45s forwards;
}
@keyframes bootWord { to { opacity: 1; transform: translateY(0); } }
.boot-bar {
  width: 120px; height: 2px;
  border-radius: 2px;
  background: var(--stone-200);
  overflow: hidden;
  margin-top: 0.2rem;
}
.boot-bar i {
  display: block; height: 100%;
  background: var(--black);
  transform-origin: left;
  transform: scaleX(0);
  transition: transform 0.5s var(--spring-flat);
}
body.booting { overflow: hidden; }
.skel-title {
  width: min(320px, 40vw); height: 3rem;
  border-radius: 0.9rem;
  background: var(--stone-200);
  margin: 1rem 0.25rem 1.5rem;
}
.bento-skel { display: grid; grid-template-columns: repeat(16, 1fr); gap: var(--gutter); }
.skel-card {
  border-radius: var(--r-card);
  corner-shape: superellipse(1.3);
  background: var(--stone-200);
  grid-column: span 4;
  aspect-ratio: 1 / 1;
  opacity: 0;
  animation: skelIn 0.6s var(--spring-soft) forwards, skelPulse 2.2s ease 0.9s infinite;
}
.skel-card.big { grid-column: span 8; grid-row: span 2; aspect-ratio: auto; }
@keyframes skelIn { from { opacity: 0; transform: scale(0.94); } to { opacity: 1; transform: scale(1); } }
@keyframes skelPulse { 0%, 100% { opacity: 1; } 50% { opacity: 0.55; } }
@media (max-width: 1024px) { .skel-card { grid-column: span 8; } .skel-card.big { grid-column: span 16; grid-row: span 1; } }
@media (max-width: 720px) { .skel-card, .skel-card.big { grid-column: span 16; } }
#scaret { position: fixed; left: 0; top: 0; width: 2px; border-radius: 1px; pointer-events: none; z-index: 99998; display: none; will-change: transform; }
#scaret.bl { animation: scaretBl 1.06s steps(1, end) 0.53s infinite; }
@keyframes scaretBl { 0% { opacity: 0; } 50% { opacity: 1; } }
#scaretRuler { position: fixed; left: -99999px; top: 0; white-space: pre; visibility: hidden; pointer-events: none; }
body.has-cursor, body.has-cursor * { cursor: none !important; }
.cursor-dot, .cursor-follow {
  position: fixed; top: 0; left: 0;
  pointer-events: none;
  opacity: 0;
  will-change: transform;
}
.cursor-dot {
  z-index: 99999;
  width: 20px; height: 20px;
  border-radius: 20px;
  background: #fff;
  border: 0.125rem solid #fff;
  mix-blend-mode: exclusion;   
  isolation: isolate;
  transition: width 0.15s var(--ease-cursor), height 0.15s var(--ease-cursor),
              opacity 0.15s var(--ease-cursor);
}
body.cursor-on .cursor-dot { opacity: 1; }
body.cursor-text .cursor-dot { width: 4px; border: none; }
body:not(.cursor-on) .cursor-dot,
body:not(.cursor-on) .cursor-follow { display: none !important; }
body.locked .cursor-dot {
  mix-blend-mode: normal; background: transparent; border-color: transparent;
  backdrop-filter: invert(1); -webkit-backdrop-filter: invert(1);
}
@keyframes seam-pill { from { background-color: rgba(250, 250, 249, .7); } to { background-color: rgba(250, 250, 249, .704); } }
body.has-cursor:not(.lite).locked:has(.player.open .player-stage.playing, .player.open .player-stage.gif) :is(.logo-pill, .nav-pill, .filter-pill) {
  animation: seam-pill 1s linear infinite alternate;
}
body.locked .cursor-arrow { opacity: 0 !important; }
body.locked.cursor-zone-card .cursor-follow { opacity: 0; backdrop-filter: none; }
body.fv-locked:not(.locked):not(.picker-open):not(:has(.appdlg:not([hidden]), .toast.actable.show)) .cursor-follow { opacity: 0 !important; }   
body.native-cursor, body.native-cursor * { cursor: auto !important; }
body.native-cursor .cursor-dot, body.native-cursor .cursor-follow { display: none !important; }
.cursor-follow {
  z-index: 99998;
  width: 0; height: 0;
  border-radius: 28px;
  background: rgba(0, 0, 0, 0.1);
  display: flex; align-items: center; justify-content: center;
  transition: width 0.15s var(--ease-cursor), height 0.15s var(--ease-cursor),
              background-color 0.15s var(--ease-cursor), opacity 0.15s var(--ease-cursor),
              backdrop-filter 0.15s var(--ease-cursor), border-radius 0.15s var(--ease-cursor);   
}
body.cursor-pointer .cursor-follow { opacity: 1; }   
body:not(.cursor-on) .cursor-follow { opacity: 0 !important; }   
body.cursor-zone-card .cursor-follow {
  opacity: 1;
  width: 80px; height: 80px;
  background: rgba(0, 0, 0, 0.4);
  backdrop-filter: blur(0.25rem);   
}
.cursor-arrow {
  width: 48px; height: 48px;
  color: #fff;
  flex: none;
  opacity: 0;                    
  transition: opacity 0.15s var(--ease-cursor);
}
body.cursor-zone-card .cursor-arrow { opacity: 1; }
.site-header {
  position: fixed;
  top: 3rem;
  left: var(--gutter); right: var(--gutter);
  z-index: 999;   
  display: grid;
  grid-template-columns: repeat(16, minmax(0, 1fr));
  column-gap: var(--gutter);
  align-items: center;
  pointer-events: none;
  font-variant-numeric: tabular-nums;
}
.site-header > * { pointer-events: auto; }
.logo-pill {
  grid-column: 1 / 3;
  justify-self: center;
  width: 6rem; aspect-ratio: 1;
  display: flex; align-items: center; justify-content: center;
  background: rgba(250, 250, 249, 0.7);
  backdrop-filter: blur(12px);
  isolation: isolate; transform: translateZ(0);   
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: var(--r-card);
  box-shadow: var(--shadow-2xl);
  color: var(--black);
}
.logo-link {
  display: block;
  width: min(62.5%, 3.5rem); aspect-ratio: 1;
  border-radius: 50%;
  margin: auto;
}
.logo-mark {
  display: block;
  width: 100%; height: 100%;
  transform-origin: center;
}
.logo-bg { transform-origin: 28px 28px; animation: logoEnter 0.6s var(--spring-soft) backwards; }
.logo-stroke { stroke-dasharray: 1 1; stroke-dashoffset: 0; animation: draw 0.5s var(--spring-flat) 0.1s backwards; }
.logo-dot { transform-box: fill-box; transform-origin: center; animation: dotpop 0.5s var(--spring-soft) 0.3s backwards; }
@keyframes logoEnter { from { transform: scale(0.25); opacity: 0; } }
@keyframes draw { from { stroke-dashoffset: 1; opacity: 0; } 20% { opacity: 1; } }
@keyframes dotpop { from { transform: scale(0.5); opacity: 0; } 60% { transform: scale(1.15); } }
.logo-link:hover .logo-mark { animation: logoBump 0.5s ease-out; }
.logo-link:hover .logo-stroke { animation: logoFlow 0.5s linear; }
.logo-link:hover .logo-dot { animation: dotBlink 0.5s ease-out; }
.boot-mark { cursor: pointer; }
.boot-mark:hover { animation: logoBump 0.5s ease-out; }
.boot-mark:hover .logo-stroke { animation: logoFlow 0.5s linear; }
.boot-mark:hover .logo-dot { animation: dotBlink 0.5s ease-out; }
@keyframes logoBump { 0% { transform: scale(1); } 30% { transform: scale(0.9); } 70% { transform: scale(1.1); } 100% { transform: scale(1); } }
@keyframes logoFlow { from { stroke-dashoffset: 0; } to { stroke-dashoffset: -2; } }
@keyframes dotBlink { 0% { transform: scale(1); opacity: 1; } 35% { transform: scale(0.5); opacity: 0; } 75% { transform: scale(1.05); opacity: 1; } 100% { transform: scale(1); } }
.header-mid {
  grid-column: 4 / 9;    
  display: flex; align-items: center; justify-content: space-between;
  gap: 2.2rem;
  font-size: 0.875rem; line-height: 1.25rem; font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: var(--black);
  animation: fadein 0.4s ease 0.2s backwards;
  transition: opacity 0.4s ease 0.2s, transform 0.4s ease 0.2s;
}
@keyframes fadein { from { opacity: 0; } }
.site-header.scrolled .header-mid,
.site-header.deep .header-mid {
  opacity: 0;
  transform: translateX(-12px);
  pointer-events: none;
  transition: opacity 0.1s ease, transform 0.1s ease;
}
.header-clock em { font-style: normal; font-weight: 600; }
.header-site {
  display: flex; align-items: center; gap: 0.6rem;
  white-space: nowrap;
}
.copy-mini {
  position: relative;
  width: 1.75rem; height: 1.75rem;
  border: 0; border-radius: 50%;
  background: var(--stone-200);
  color: var(--black);
  transition: transform 0.2s var(--spring-soft), background 0.2s;
}
.copy-mini:active { transform: scale(0.8); }
.copy-mini .ic {
  position: absolute; inset: 0; margin: auto;
  width: 1rem; height: 1rem;
  transition: opacity 0.15s, transform 0.5s var(--spring-soft);
}
.copy-mini .ic-copy { opacity: 1; transform: scale(1); }
.copy-mini .ic-check { opacity: 0; transform: scale(0.5); }
.copy-mini.copied .ic-copy { opacity: 0; transform: scale(1.5); transition: opacity 0.15s, transform 0.15s; }
.copy-mini.copied .ic-check { opacity: 1; transform: scale(1); }
.copied-tip {
  position: absolute;
  bottom: calc(100% + 6px); left: 50%;
  background: var(--black); color: var(--stone-100);
  font-size: 0.75rem; font-weight: 700;
  border-radius: 999px;
  padding: 0.3rem 0.7rem;
  pointer-events: none;
  white-space: nowrap;
  opacity: 0;
  transform: translate(-50%, 24px) scale(0.5);
  transition: transform 0.15s ease, opacity 0.15s;
}
.copy-mini.copied .copied-tip {
  opacity: 1;
  transform: translate(-50%, -4px) scale(1);
  transition: transform 0.5s cubic-bezier(0.3, 1.5, 0.5, 1), opacity 0.2s;
}
@media (max-width: 1024px) { .header-mid { display: none; } }
.nav-pill {
  grid-column: 10 / 17;
  justify-self: end;
  margin-right: calc(var(--col-w) * 0.5);   
  max-width: 100%;
  display: flex; align-items: center;
  min-height: 3.5rem;
  padding: 0 calc(0.625rem - 1px);   
  background: rgba(250, 250, 249, 0.7);
  backdrop-filter: blur(12px);
  isolation: isolate; transform: translateZ(0);   
  border: 1px solid rgba(255, 255, 255, 0.65);
  border-radius: var(--r-card);                    
  box-shadow: var(--shadow-2xl);
}
@media (min-width: 769px) and (max-width: 1024px) { .nav-pill { grid-column: 4 / 17; } }
.nav-items {
  overflow: hidden;
  opacity: 1;
  transition: width 0.5s var(--spring-flat), height 0.5s var(--spring-flat), opacity 0.35s ease 0.1s;
  min-width: 0;   
}
.nav-items.nav-settled { overflow: visible; }
.nav-items-inner {
  display: flex; align-items: center; gap: 0.25rem;   
  width: max-content;
}
.nav-pill.condensed:not(.mobile-open) .nav-items {
  opacity: 0;
  pointer-events: none;
  transition: width 0.5s var(--spring-flat), height 0.5s var(--spring-flat), opacity 0.2s;
}
.nav-link {
  height: 2.5rem;
  padding: 0 0.75rem;
  border: 0; background: transparent;
  font-family: var(--font-sans);
  font-size: 1.25rem; line-height: 1.75rem; font-weight: 700;
  color: var(--black);
  border-radius: var(--r-card);
  corner-shape: superellipse(1.3);   
  white-space: nowrap;
}
.nav-pill .pill-btn { font-size: 1.25rem; padding-left: 1rem; padding-right: 0.75rem; margin-left: 0.75rem; }   
.nav-pill .pill-btn svg { width: 1.25rem; height: 1.25rem; }
.nav-burger {
  width: 0; height: 2.5rem;
  padding: 0;
  border: 0; background: transparent;
  color: var(--black);
  overflow: hidden;
  opacity: 0;
  border-radius: var(--r-card); corner-shape: superellipse(1.3);   
  transition: width 0.5s var(--spring-flat), opacity 0.3s;
  flex: none;
  display: flex; align-items: center; justify-content: center;
}
.nav-pill.condensed .nav-burger { width: 3.25rem; opacity: 1; transition: width 0.5s var(--spring-flat), opacity 0.3s 0.15s; }
.nav-burger svg { width: 2.5rem; height: 2.5rem; flex: none; }
.bl { stroke-dasharray: 1 1; stroke-dashoffset: 0; }
.bdot { transform-origin: 26px 23.5px; }
.nav-pill.condensed .bl1 { animation: bdraw 1s var(--spring-flat) 0.2s backwards; }
.nav-pill.condensed .bl2 { animation: bdraw 1s var(--spring-flat) 0.3s backwards; }
.nav-pill.condensed .bl3 { animation: bdraw 1s var(--spring-flat) 0.4s backwards; }
.nav-pill.condensed .bdot { animation: dotpop 0.5s var(--spring-soft) 0.6s backwards; }
@keyframes bdraw { from { stroke-dashoffset: 1; opacity: 0; } 15% { opacity: 1; } }
.nav-burger:hover .bl1 { animation: bflow 1s linear; }
.nav-burger:hover .bl2 { animation: bflow 1s linear 0.06s; }
.nav-burger:hover .bl3 { animation: bflow 1s linear 0.12s; }
.nav-burger:hover .bdot { animation: dotBlink 1s ease-out; }
@keyframes bflow { from { stroke-dashoffset: 0; } to { stroke-dashoffset: -2; } }
.nav-dim { position: fixed; inset: 0; z-index: 998; background: transparent; }
.pill-btn {
  display: inline-flex; align-items: center; gap: 0.5rem;
  height: 2.5rem;
  padding: 0 1.15rem;
  border: 0;
  border-radius: var(--r-card);
  corner-shape: superellipse(1.3);
  background: var(--black);
  color: var(--stone-100);
  font-family: var(--font-sans);
  font-size: 1rem; font-weight: 700;
  text-decoration: none;
  white-space: nowrap;   
}
.pill-btn svg { width: 1.1em; height: 1.1em; }
.pill-ghost { background: var(--stone-200); color: var(--black); }
.page { position: relative; z-index: 1; background: var(--stone-50); }
.hero { padding: 16rem var(--pad-x) 4rem; overflow-x: clip; }   
.hero-copy {
  font-weight: 700;
  font-size: clamp(1.5rem, 0.7rem + 2.9vw, 3.5rem);
  line-height: 1.4;
  letter-spacing: -0.01em;
  max-width: none;
  text-align: center;   
}
.hero-line { display: block; will-change: transform, opacity, filter; }
.hp-seg { display: inline-block; white-space: nowrap; }
.hero-slot {
  display: inline-flex; align-items: flex-start; justify-content: center;   
  overflow: hidden;
  vertical-align: baseline;               
  transform: translateY(-1.5px);          
  height: var(--slot-h, 1.42em);          
  margin: 0 0.264em 0 0.32em;
  padding: 0 0.5em;                       
  background: var(--black);
  color: var(--stone-50);
  border-radius: calc(var(--slot-h, 1.42em) * 0.425);   
  corner-shape: superellipse(1.3);        
  width: var(--slot-w, auto);
}
.hero-slot-reel {
  display: flex; flex-direction: column;
  width: 100%;   
  transition: transform 0.52s cubic-bezier(0.16, 1, 0.3, 1);
}
.hero-slot-item {
  width: 100%;      
  height: var(--slot-h, 1.42em);   
  display: flex; align-items: center; justify-content: center;
  white-space: nowrap;
  font-weight: 700; letter-spacing: -0.01em;
}
.hero-links {
  display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap;
  gap: 1rem;
  margin-top: 3.5rem;
  padding-left: 0;
}
.hero-stats { font-size: 0.95rem; font-weight: 600; color: var(--stone-500); font-variant-numeric: tabular-nums; }
.hero-stats b { color: var(--black); }
.arrow-link {
  position: relative;
  display: inline-flex; align-items: center;
  font-size: 1.25rem; font-weight: 700;
  color: var(--black);
  text-decoration: none;
  padding: 0.25rem 0;
}
.arrow-link .al-text {
  display: inline-block;
  margin: 0 0.625em;
  transform: translateX(-0.625em);
  transition: transform 0.35s var(--spring-flat);
}
.al-arrow {
