  :is(#catPills .pill, #typePills .pill, #typeToggle, #folderPills .pill, #sgLegend .ac-dom)::after {
    content: ''; position: absolute; inset: 0; z-index: -1; pointer-events: none; border-radius: inherit;
    background: linear-gradient(rgba(12, 10, 9, .12), rgba(12, 10, 9, .12)) left / 0% 100% no-repeat; opacity: 0;
