  :is(#catPills .pill, #typePills .pill, #typeToggle, #folderPills .pill, #sgLegend .ac-dom).lp-deep::after { opacity: 1; background-size: 100% 100%; transition: opacity .06s, background-size .27s cubic-bezier(.3, 0, .7, 1); }
  :is(#catPills .pill, #typePills .pill, #typeToggle, #folderPills .pill, #sgLegend .ac-dom).lp-press:not(.lp-deep)::after { opacity: 0; background-size: 0% 100%; transition: none; }
